  -- Ambil satu user admin / akun pertama di auth.users sebagai pembuat historis
  SELECT id INTO v_admin_id FROM auth.users ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM public.pn_profil LIMIT 1;
  END IF;

  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Tidak ada user terdaftar di auth.users / pn_profil untuk dikaitkan.';
