  -- RE-ENABLE AUDIT TRIGGER
  ALTER TABLE public.pn_nomor ENABLE TRIGGER trg_pn_nomor_audit;

  -- PASTIKAN COUNTER TERAKHIR TETAP SELARAS DENGAN DATA MAKSIMAL
  UPDATE public.pn_counter c
  SET terakhir = sub.max_no
  FROM (
    SELECT jenis_id, tahun, MAX(no_urut) as max_no
    FROM public.pn_nomor
    WHERE tahun = 2026
    GROUP BY jenis_id, tahun
  ) sub
  WHERE c.jenis_id = sub.jenis_id AND c.tahun = sub.tahun AND sub.max_no > c.terakhir;

  RAISE NOTICE '✅ Berhasil mengimpor 889 data riwayat nomor surat tahun 2026 ke database!';
